const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry - Indus River floodplain in Pakistan
  const geometry = ee.Geometry.Polygon([
    [
      [67.0, 23.5],  // Southwest
      [67.0, 30.0],  // Northwest
      [75.0, 30.0],  // Northeast
      [75.0, 23.5],  // Southeast
      [67.0, 23.5]   // Closing
    ]
  ]);

  // 2. Date ranges
  const startDate1 = '2022-07-01';
  const endDate1 = '2022-07-15';
  const startDate2 = '2022-08-15';
  const endDate2 = '2022-08-28';

  // Function to get Sentinel-2 collection
  function getS2Collection(startDate, endDate) {
    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));
  }

  // Function to get Landsat 8/9 collection (fallback)
  function getLandsatCollection(startDate, endDate) {
    const landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(geometry)
      .filterDate(startDate, endDate);
    const landsat9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(geometry)
      .filterDate(startDate, endDate);
    return landsat8.merge(landsat9);
  }

  // Function to process image collection (cloud mask + MNDWI)
  function processCollection(collection, isSentinel) {
    if (isSentinel) {
      // Sentinel-2 processing
      return collection
        .map(function(image) {
          // Cloud masking for Sentinel-2
          const qa = image.select('QA60');
          const cloudBitMask = 1 << 10;
          const cirrusBitMask = 1 << 11;
          const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
            .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

          // Calculate MNDWI for water detection
          const mndwi = image.normalizedDifference(['B3', 'B11'])
            .rename('mndwi');

          return image.updateMask(mask)
            .addBands(mndwi)
            .select(['mndwi']);
        })
        .median()
        .clip(geometry);
    } else {
      // Landsat processing
      return collection
        .map(function(image) {
          // Apply scaling factors for Landsat
          const opticalBands = image.select('SR_B.').multiply(0.0000275).add(-0.2);
          const thermalBands = image.select('ST_B.*').multiply(0.00341802).add(149.0);

          // Cloud masking using QA_PIXEL band
          const qa = image.select('QA_PIXEL');
          const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)
            .and(qa.bitwiseAnd(1 << 4).eq(0));

          // Calculate MNDWI (Green = B3, SWIR1 = B6)
          const mndwi = opticalBands.normalizedDifference(['SR_B3', 'SR_B6'])
            .rename('mndwi');

          return image.addBands(opticalBands, null, true)
            .addBands(thermalBands, null, true)
            .addBands(mndwi)
            .updateMask(cloudMask)
            .select(['mndwi']);
        })
        .median()
        .clip(geometry);
    }
  }

  // Function to get water area count
  function getWaterArea(image) {
    // Water mask: MNDWI > 0 (typical threshold for water)
    const waterMask = image.select('mndwi').gt(0);

    // Count water pixels
    const stats = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    });

    return stats.get('mndwi');
  }

  // 3. Try to get data for both periods
  let col1 = getS2Collection(startDate1, endDate1);
  let col2 = getS2Collection(startDate2, endDate2);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  // If Sentinel-2 collections are empty, try Landsat as fallback
  let isSentinel1 = true, isSentinel2 = true;

  if (size1 === 0) {
    col1 = getLandsatCollection(startDate1, endDate1);
    isSentinel1 = false;
  }
  if (size2 === 0) {
    col2 = getLandsatCollection(startDate2, endDate2);
    isSentinel2 = false;
  }

  // Check final collection sizes
  const finalSize1 = col1.size().getInfo();
  const finalSize2 = col2.size().getInfo();

  console.log(`Period 1 (${startDate1} to ${endDate1}): ${finalSize1} images`);
  console.log(`Period 2 (${startDate2} to ${endDate2}): ${finalSize2} images`);

  // Check for empty collections
  if (finalSize1 === 0 || finalSize2 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Process collections
  const img1 = processCollection(col1, isSentinel1);
  const img2 = processCollection(col2, isSentinel2);

  // 5. Get water areas
  const waterArea1 = getWaterArea(img1).getInfo();
  const waterArea2 = getWaterArea(img2).getInfo();

  console.log(`Water pixels Period 1: ${waterArea1}`);
  console.log(`Water pixels Period 2: ${waterArea2}`);

  // Check for no valid pixels
  if (waterArea1 === null || waterArea2 === null || 
      (waterArea1 === 0 && waterArea2 === 0)) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for calculation failures
  if (waterArea1 === undefined || waterArea2 === undefined ||
      isNaN(waterArea1) || isNaN(waterArea2) ||
      waterArea1 < 0 || waterArea2 < 0) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Compare and determine answer
  const changePercent = ((waterArea2 - waterArea1) / waterArea1 * 100);
  console.log(`Change: ${changePercent.toFixed(1)}%`);

  // Consider any increase as "Yes" (even small increases)
  if (waterArea2 > waterArea1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
